import sys
p=sys.argv[1]; s=open(p,encoding='utf-8').read()
def rep(old,new):
    global s
    n=s.count(old); assert n==1,(old[:80],n); s=s.replace(old,new)
rep("""  heat:{t:'Heat stress',w:'Risk to people from humid heat, on a 0-100 scale.',s:'Live temperature + humidity (MACH); terrain from the DEM.',m:'Wet-bulb temperature, banded to 0-100. Wet-bulb captures the body\\'s evaporative cooling limit. Where the unit\\'s elevation is known it is solved psychrometrically at that pressure; where it is not, the Stull (2011) sea-level regression is used and the panel says so. Pressure IS in the wet-bulb equation - an earlier version of this note said it was not, and the score ran up to 1.4 C warm through Gilgit-Baltistan and Balochistan as a result.',l:'Decision-support score, not a heat warning. Uncalibrated until validated against heat-mortality records.'},""",
"""  heat:{t:'Heat stress',w:'Heat stress for people outdoors in shade, as a level from Normal to Severe.',s:'MACH forecast temperature, humidity and wind.',m:'UTCI in shade (the Universal Thermal Climate Index, Br\\u00f6de et al. 2012) at the hottest hour of each day. The level follows the published UTCI heat-stress classes: Low from 26 \\u00b0C (the end of no thermal stress), Moderate from 32 (moderate heat stress), High from 38 (strong), Severe from 46 (very strong).',l:'A forecast screening level, not a heat warning or a health forecast. Checked against AGN and partner weather stations: in the plains it rises on the days the stations record heat stress; on humid days on the Sindh coast and in mountain valleys it can read one level lower than the stations, and on the hottest days of a hot spell it can read one level low. Sun, work and clothing add stress the level does not count.'},""")
rep("""  wind:{t:'Wind and gusts',w:'Risk from wind and gusts on a 0-100 scale.',s:'Live wind + gust (MACH); terrain ruggedness (TRI) from DEM.',m:'Gust load on a declared ladder anchored to Beaufort and Saffir-Simpson: 40 km/h damage onset, 62 gale, 89 storm, 118 hurricane force, 160 Cat 1-2 gust field, saturating at 220 km/h. Amplified by terrain ruggedness (TRI).',""",
"""  wind:{t:'Wind and gusts',w:'Wind and gust load, as a level from Normal to Severe.',s:'MACH forecast wind and gusts.',m:'The day\\'s highest forecast gust on a ladder anchored to the Beaufort scale (40 km/h where scoring starts, 62 gale, 89 storm, 118 hurricane force): Low from about 58 km/h, Moderate from about 78, High from about 102, Severe from about 130. Not scored above 1,500 m, where model gusts did not match mountain stations.',""")
rep("""l:'OPEN ITEM DEV-01 — cross-engine parity. This HTML is the canonical wind engine (the interpolated ladder [[40,0],[62,30],[89,55],[118,78],[160,92],[220,100]] — onset 40 km/h is its first breakpoint and 1.3636 its first segment; it is piecewise, not a straight line). methods.py and hazardEngine.js still carry the legacy 18 km/h / x3.0 curve, so the same inputs can produce different scores in the backend and React implementations. Migration of those engines is a backend acceptance gate: one wind fixture, one score, in all four implementations. Scores shown here are the canonical ones.'},""",
"""l:'Gusts from thunderstorms and dust storms are short and local, and the forecast models rarely place them: checked against weather stations, the level seldom rises on a day a station records a strong gust. Read it as the wind of the large-scale weather; a storm warning from the national warning authorities overrides it.'},""")
rep("""  cold:{t:'Cold stress and frost',w:'Cold-wave risk, only active in highland zones.',s:'Live temperature (MACH); elevation from DEM.',m:'Cold stress below temperature thresholds, amplified with elevation, gated so only highland districts score.',l:'Lowland districts correctly score zero. Uncalibrated until validated against cold-wave records.'},""",
"""  cold:{t:'Cold stress and frost',w:'Cold stress for people outdoors, as a level from Normal to Severe.',s:'MACH forecast temperature, humidity and wind.',m:'UTCI in shade at the coldest hour of each day, on the published UTCI cold-stress classes: Low from 0 \\u00b0C (moderate cold stress), Moderate from \\u221213 (strong), High from \\u221227 (very strong), Severe from \\u221240 (extreme).',l:'A screening level, not a frost or cold-wave warning. It has not yet been checked on a winter of forecasts (the station check so far covers an autumn with no recorded cold stress); in mountain valleys the forecast models run colder than the stations on clear nights, so the level can read high there. Snow is not scored: there is no separate snow level.'},""")
rep("""  glof:{t:'Glacial lake outburst flood (GLOF)',w:'Glacial lake outburst flood risk.',s:'Static GLOF lake inventory (ICIMOD and the national GLOF programme); elevation from DEM.',m:'Inventory-based scoring from known glacial-lake proximity and elevation.',l:'Inventory-based, not a live outburst forecast. Indicates standing exposure, not an imminent event.'},""",
"""  glof:{t:'Glacial lake outburst flood (GLOF)',w:'Exposure to an outburst from the glacial lakes upstream, as a level: Normal, High or Severe.',s:'SUPARCO glacial-lake inventory (Glacier Geospatial Portal) and SUPARCO GLOF bulletins; the 2024 national inventory where SUPARCO holds no record; open inventories (Hi-MAG, RGI 7.0, HMAGLOFDB); Copernicus DEM and HydroBASINS; our own Sentinel-2 reads of lake area.',m:'Each lake\\'s outburst susceptibility (a model fitted on documented outbursts) is routed 100 km down the river network. A tehsil is Normal when the lakes upstream add up to little or are only susceptible (a standing condition), High when a lake within reach shows a precursor (growth in our satellite reads), Severe on an observed drainage or a confirmed outburst report.',l:'A screening of standing exposure, not an outburst forecast or a flood extent. Lakes change between satellite reads, and small lakes are not read every month.'},""")
open(p,'w',encoding='utf-8').write(s); print('info patched')
